{
  "name": "惠普 HP6652A 单路可编程直流电源",
  "name_en": "HP 6652A Single-Output Programmable DC Power Supply",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 6652A 是一台单路可编程直流台式电源，用于为实验装置、电子电路和原型系统提供稳定的电压与电流输出。它适合实验室中的供电、调试和基础电源测试，并支持输出开关、过压/过流保护以及前面板显示功能。",
  "description_en": "The HP 6652A is a single-output programmable bench DC power supply used to provide stable voltage and current to laboratory setups, electronic circuits, and prototype systems. It is suitable for powering, debugging, and basic power testing, and supports output enable control, overvoltage/overcurrent protection, and front-panel display functions.",
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取/设置输出电流设定值",
      "description_en": "get/set the output current setting"
    },
    {
      "action_name": "auto-display_text",
      "description": "在前面板显示屏上显示文本",
      "description_en": "display text on the front-panel screen"
    },
    {
      "action_name": "auto-display_textmode",
      "description": "获取/设置前面板文本显示模式",
      "description_en": "get/set the front-panel text display mode"
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置工作模式",
      "description_en": "get/set the operating mode"
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置输出开关状态",
      "description_en": "get/set the output enable state"
    },
    {
      "action_name": "auto-overcurrent",
      "description": "获取/设置过流保护设置",
      "description_en": "get/set the overcurrent protection setting"
    },
    {
      "action_name": "auto-overvoltage",
      "description": "获取/设置过压保护设置",
      "description_en": "get/set the overvoltage protection setting"
    },
    {
      "action_name": "auto-reset",
      "description": "复位过压和过流故障以恢复工作",
      "description_en": "reset overvoltage and overcurrent faults to resume operation"
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置输出电压设定值",
      "description_en": "get/set the output voltage setting"
    },
    {
      "action_name": "auto-name",
      "description": "获取仪器标识字符串",
      "description_en": "get the instrument identification string"
    },
    {
      "action_name": "auto-channel",
      "description": "获取通道信息（本机为单通道）",
      "description_en": "get the channel information (single-channel instrument)"
    }
  ],
  "tag_hints": [
    "programmable DC power supply",
    "single-output bench supply",
    "voltage and current sourcing",
    "overvoltage protection",
    "overcurrent protection",
    "electronics testing",
    "SCPI instrument"
  ]
}

